{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "GSK269984A, the closest analogue sharing a carboxylic acid and halogenated diaryl ether/benzyl motif, had an absolute oral bioavailability of 95% in healthy volunteers after oral and i.v. microdosing.",
      "evidence_role": "supportive"
    },
 {
      "card_ids": ["C05"],
      "claim": "Tetomilast, which shares a carboxylic acid, alkoxy-substituted aryl, and heteroaromatic core, showed nearly 100% absolute oral bioavailability in COPD patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "S/GSK1349572, a fused heterocyclic carboxylic acid with methoxy and fluorobenzyl substituents similar to the query, demonstrated good oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Abecarnil, a fused heteroaromatic with methoxy and benzyl ether features, had an absolute oral bioavailability of 39 ± 17% in healthy volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Norfloxacin, a fused heterocyclic carboxylic acid with fluorine substitution, has human oral bioavailability of 30–40%, supporting high bioavailability at the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Letermovir, a complex heteroaromatic with methoxy and fluorinated aryl groups, had an absolute bioavailability of 1.00 in healthy participants.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability: closest analogues with carboxylic acid, fused heteroaromatic, and fluorinated/alkoxy aryl features show absolute F values from about 35% to nearly 100% in humans, all above the 20% threshold. No affirmative experimental evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "Morgan similarities to the evidence molecules are low (0.20–0.23), limiting structural transferability.",
    "The query's high lipophilicity and low aqueous solubility could affect formulation-dependent absorption, but this is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

